-- Feature 22: append-only local fixture evidence. It has no product authority.
CREATE TABLE IF NOT EXISTS product_eligibility_scopes(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_feature21_contexts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,run_id text NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,run_id),UNIQUE(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_sources(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,source_id text NOT NULL,revision integer NOT NULL CHECK(revision>0),artifact_hash char(64) NOT NULL,predecessor_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,source_id,revision),UNIQUE(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_owner_claims(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_attribute_assertions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_product_bindings(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_venue_bindings(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_rulepacks(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,rulepack_id text NOT NULL,revision integer NOT NULL CHECK(revision>0),artifact_hash char(64) NOT NULL,predecessor_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,rulepack_id,revision),UNIQUE(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_clauses(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,rulepack_hash char(64) NOT NULL,clause_id text NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,rulepack_hash,clause_id),UNIQUE(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,rulepack_hash) REFERENCES product_eligibility_rulepacks(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_golden_manifests(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_golden_case_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,manifest_hash char(64) NOT NULL,case_id text NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,manifest_hash,case_id),UNIQUE(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash,manifest_hash) REFERENCES product_eligibility_golden_manifests(operator_test_id,scope_hash,artifact_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_changes(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_quorum_bindings(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_activation_receipts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,sequence integer NOT NULL CHECK(sequence>0),artifact_hash char(64) NOT NULL,predecessor_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,sequence),UNIQUE(operator_test_id,scope_hash,artifact_hash),CHECK((sequence=1 AND predecessor_hash IS NULL) OR (sequence>1 AND predecessor_hash IS NOT NULL)),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_requests(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,request_hash char(64) NOT NULL,feature21_context_hash char(64) NOT NULL,product_binding_hash char(64) NOT NULL,venue_binding_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,request_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_decisions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,decision_hash char(64) NOT NULL,request_hash char(64) NOT NULL,expires_at timestamptz NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,decision_hash),UNIQUE(operator_test_id,scope_hash,request_hash),FOREIGN KEY(operator_test_id,scope_hash,request_hash) REFERENCES product_eligibility_requests(operator_test_id,scope_hash,request_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_leaf_results(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,decision_hash char(64) NOT NULL,jurisdiction_role text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,decision_hash,jurisdiction_role),FOREIGN KEY(operator_test_id,scope_hash,decision_hash) REFERENCES product_eligibility_decisions(operator_test_id,scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_lifecycle_transitions(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,transition_hash char(64) NOT NULL,predecessor_hash char(64),payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,transition_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_artifacts(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,artifact_kind text NOT NULL,artifact_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,artifact_kind,artifact_hash),FOREIGN KEY(operator_test_id,scope_hash) REFERENCES product_eligibility_scopes(operator_test_id,scope_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_test_center_bundles(operator_test_id text NOT NULL,scope_hash char(64) NOT NULL,decision_hash char(64) NOT NULL,run_id text NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,scope_hash,decision_hash),FOREIGN KEY(operator_test_id,scope_hash,decision_hash) REFERENCES product_eligibility_decisions(operator_test_id,scope_hash,decision_hash));
CREATE TABLE IF NOT EXISTS product_eligibility_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key));
CREATE TABLE IF NOT EXISTS product_eligibility_conflicts(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key,request_hash));
CREATE OR REPLACE FUNCTION product_eligibility_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'product_eligibility_append_only'; END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['product_eligibility_scopes','product_eligibility_feature21_contexts','product_eligibility_sources','product_eligibility_owner_claims','product_eligibility_attribute_assertions','product_eligibility_product_bindings','product_eligibility_venue_bindings','product_eligibility_rulepacks','product_eligibility_clauses','product_eligibility_golden_manifests','product_eligibility_golden_case_receipts','product_eligibility_changes','product_eligibility_quorum_bindings','product_eligibility_activation_receipts','product_eligibility_requests','product_eligibility_decisions','product_eligibility_leaf_results','product_eligibility_lifecycle_transitions','product_eligibility_artifacts','product_eligibility_test_center_bundles','product_eligibility_request_claims','product_eligibility_conflicts'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS product_eligibility_no_mutation ON %I',t); EXECUTE format('CREATE TRIGGER product_eligibility_no_mutation BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION product_eligibility_append_only()',t); END LOOP; END $$;
CREATE OR REPLACE VIEW product_eligibility_current_fixture_projection AS SELECT operator_test_id,scope_hash,count(*) AS decision_count,array_agg(DISTINCT payload->>'outcome') AS outcomes FROM product_eligibility_decisions GROUP BY operator_test_id,scope_hash;
